public final class ApiTest {
    private ApiTest() {}

    public static void main(String[] args) {
        try {
            String grid_png = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_A2/experiments/external/thumbnailator/source/src/test/resources/Thumbnailator/grid.png";
    String grid_jpeg = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_A2/experiments/external/thumbnailator/source/src/test/resources/Thumbnailator/grid.jpg";
    String exif_jpeg = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_A2/experiments/external/thumbnailator/source/src/test/resources/Exif/original.jpg";
    String output_dir = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_A2/experiments/external/thumbnailator/.aideal_exec/A2/output";

    // pre-loaded typed inputs (comprehension.execute.preamble)
    BufferedImage sourceImage = new BufferedImage(32, 24, BufferedImage.TYPE_INT_RGB);
    Graphics2D graphics = sourceImage.createGraphics();
    graphics.setColor(Color.BLUE);
    graphics.fillRect(0, 0, 32, 24);
    graphics.setColor(Color.YELLOW);
    graphics.fillRect(8, 6, 16, 12);
    graphics.dispose();
    BufferedImage destinationImage = new BufferedImage(16, 12, BufferedImage.TYPE_INT_RGB);
    ByteArrayOutputStream imageBytes = new ByteArrayOutputStream();
    Path outputPath = Paths.get(output_dir, "thumbnail.png");
    Files.createDirectories(outputPath.getParent());

            // TODO API_TEST_START
            java.io.File outDir = new java.io.File(output_dir);
            if (!outDir.exists()) {
                outDir.mkdirs();
            }

            // Copy fixtures to the output directory to avoid polluting the source directory
            java.io.File f1 = new java.io.File(outDir, "fromFiles_test1.png");
            java.io.File f2 = new java.io.File(outDir, "fromFiles_test2.jpg");
            java.nio.file.Files.copy(new java.io.File(grid_png).toPath(), f1.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
            java.nio.file.Files.copy(new java.io.File(grid_jpeg).toPath(), f2.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING);

            java.util.List<java.io.File> sources = java.util.Arrays.asList(f1, f2);

            // Initialize the pipeline from the collection of files
            java.util.List<java.io.File> results = net.coobird.thumbnailator.Thumbnails.fromFiles(sources)
                    .size(42, 42)
                    .asFiles(net.coobird.thumbnailator.name.Rename.PREFIX_DOT_THUMBNAIL);

            assert results != null && results.size() == 2 : "Expected exactly 2 generated thumbnail files";
            assert results.get(0).exists() : "First thumbnail file must exist on disk";
            assert results.get(1).exists() : "Second thumbnail file must exist on disk";
            assert results.get(0).getName().startsWith("thumbnail.") : "First thumbnail should have the correct rename prefix";
            assert results.get(1).getName().startsWith("thumbnail.") : "Second thumbnail should have the correct rename prefix";

            java.awt.image.BufferedImage thumb1 = javax.imageio.ImageIO.read(results.get(0));
            assert thumb1 != null : "Thumbnail 1 should be readable as an image";
            assert thumb1.getWidth() <= 42 && thumb1.getHeight() <= 42 : "Thumbnail dimensions should be constrained to 42x42";

            System.out.println("__CHECK__ fromFiles " + results.size() + " files generated, first is " + results.get(0).getName());
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
                    + ": " + exc.getMessage());
            exc.printStackTrace(System.err);
            System.exit(1);
        }
    }
}
